const crypto = require('crypto');
const headers = $json.headers ?? {};
const tokenHeader = headers['x-govhub-token'] || headers['X-GOVHUB-TOKEN'];
const allowed = String($env.GOVHUB_TOKENS || '').split(',').map(v => v.trim()).filter(Boolean);
if (!tokenHeader || !allowed.includes(String(tokenHeader).trim())) {
  return [{ json: { route: 'error', statusCode: 401, status: 'unauthorized', error_code: 'AUTH_INVALID_TOKEN', message: 'invalid token' } }];
}
let body = $json.body ?? {};
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch { body = {}; }
}
const required = ['snapshot_type','protocol','version','encoding','compression','payload_b64','payload_sha256','payload_size_bytes','created_by'];
for (const k of required) {
  if (body[k] === undefined || body[k] === null || String(body[k]).trim() === '') {
    return [{ json: { route: 'error', statusCode: 400, status: 'invalid_request', error_code: 'SNAPSHOT_INVALID_PAYLOAD', message: 'missing field: ' + k } }];
  }
}
if (String(body.protocol) !== 'UBIN') {
  return [{ json: { route: 'error', statusCode: 400, status: 'invalid_request', error_code: 'SNAPSHOT_PROTOCOL_INVALID', message: 'protocol must be UBIN' } }];
}
if (String(body.encoding) !== 'json' || String(body.compression) !== 'gzip') {
  return [{ json: { route: 'error', statusCode: 400, status: 'invalid_request', error_code: 'SNAPSHOT_ENCODING_INVALID', message: 'encoding/compression must be json+gzip' } }];
}
let zipped;
try {
  zipped = Buffer.from(String(body.payload_b64), 'base64');
} catch (e) {
  return [{ json: { route: 'error', statusCode: 400, status: 'invalid_request', error_code: 'SNAPSHOT_DECODE_FAILED', message: 'payload_b64 is not valid base64' } }];
}
if (!zipped || zipped.length === 0) {
  return [{ json: { route: 'error', statusCode: 400, status: 'invalid_request', error_code: 'SNAPSHOT_DECODE_FAILED', message: 'payload_b64 is empty or invalid' } }];
}
if (zipped.length > 262144) {
  return [{ json: { route: 'error', statusCode: 400, status: 'invalid_request', error_code: 'SNAPSHOT_SIZE_LIMIT', message: 'compressed payload exceeds 256KB limit' } }];
}
const sha = crypto.createHash('sha256').update(zipped).digest('hex');
if (sha !== String(body.payload_sha256).trim()) {
  return [{ json: { route: 'error', statusCode: 400, status: 'invalid_request', error_code: 'SNAPSHOT_SHA_MISMATCH', message: 'payload_sha256 mismatch' } }];
}
// Phase 1 scan: transport payload + base64-decoded bytes (no gunzip in task runner).
const payloadB64Text = String(body.payload_b64);
const decodedText = zipped.toString('utf8');
const secretPattern = /(PRIVATE KEY|AWS_ACCESS_KEY_ID|AWS_SECRET_ACCESS_KEY|ghp_|github_pat_|xoxb-|token=|password=|secret=)/i;
const keyPattern = /"(token|password|secret|api_key)"\s*:/i;
if (secretPattern.test(payloadB64Text) || secretPattern.test(decodedText) || keyPattern.test(decodedText)) {
  return [{ json: { route: 'error', statusCode: 400, status: 'rejected', error_code: 'SNAPSHOT_SECRET_DETECTED', message: 'snapshot rejected by secret scan policy' } }];
}
const esc = (v) => String(v ?? '').replace(/'/g, "''");
return [{ json: {
  route: 'valid',
  snapshot_type: String(body.snapshot_type),
  protocol: String(body.protocol),
  version: String(body.version),
  encoding: String(body.encoding),
  compression: String(body.compression),
  payload_b64: String(body.payload_b64),
  payload_sha256: String(body.payload_sha256),
  payload_size_bytes: Number(body.payload_size_bytes),
  created_by: String(body.created_by),
  source_repo: body.source_repo ? String(body.source_repo) : '',
  source_ref: body.source_ref ? String(body.source_ref) : '',
  snapshot_type_sql: esc(body.snapshot_type),
  protocol_sql: esc(body.protocol),
  version_sql: esc(body.version),
  encoding_sql: esc(body.encoding),
  compression_sql: esc(body.compression),
  payload_b64_sql: esc(body.payload_b64),
  payload_sha256_sql: esc(body.payload_sha256),
  created_by_sql: esc(body.created_by),
  source_repo_sql: esc(body.source_repo ?? ''),
  source_ref_sql: esc(body.source_ref ?? '')
} }];
